import { useState, useEffect, useCallback, useRef } from 'react';
import { WalletProvider, useWallet } from '@solana/wallet-adapter-react';
import { WalletModalProvider, useWalletModal } from '@solana/wallet-adapter-react-ui';
import type { WalletName } from '@solana/wallet-adapter-base';
import { useSolanaAuth } from '../../hooks/useSolanaAuth';
import { LoadingSpinner } from '../shared/LoadingSpinner';

export interface SolanaLoginButtonProps {
  onSuccess?: () => void;
  onError?: (error: Error) => void;
  className?: string;
  variant?: 'default' | 'outline';
  size?: 'sm' | 'md' | 'lg';
  disabled?: boolean;
  /**
   * Hide the button if no Solana wallets are detected.
   * When true (default), button renders nothing if no wallets are installed.
   * When false, button always renders (useful for showing "install wallet" prompts).
   * @default true
   */
  hideIfNoWallet?: boolean;
  /** Called when the button's loading state changes (connecting, signing, etc.). */
  onLoadingChange?: (loading: boolean) => void;
  /**
   * Solana wallet adapter context. Pass this from @solana/wallet-adapter-react's useWallet().
   * When provided, the component assumes a WalletProvider exists in the React tree and
   * uses the consumer's wallet context for wallet discovery and connection.
   * When omitted, the component provides its own WalletProvider with wallet-standard discovery.
   */
  walletContext?: {
    publicKey: { toBase58: () => string } | null;
    signMessage: ((message: Uint8Array) => Promise<Uint8Array>) | null;
    connected: boolean;
    connecting: boolean;
    connect: () => Promise<void>;
    wallet: { adapter: { name: string } } | null;
    select: (walletName: string) => void;
    wallets: Array<{
      adapter: {
        name: string;
        icon: string;
        readyState: string;
      };
    }>;
  };
}

/** Stable empty array to avoid re-renders in self-contained WalletProvider. */
const EMPTY_ADAPTERS: [] = [];

/**
 * Solana wallet login button with one-click authentication.
 *
 * Uses the standard wallet adapter modal for wallet selection, which provides
 * real brand icons and discovers all wallet-standard-compliant wallets.
 *
 * When `walletContext` is provided, assumes a WalletProvider exists in the tree.
 * Otherwise, wraps itself with WalletProvider for self-contained operation.
 */
export function SolanaLoginButton(props: SolanaLoginButtonProps) {
  if (props.walletContext) {
    // Consumer has their own WalletProvider; just add modal capability
    return (
      <WalletModalProvider>
        <SolanaLoginInner {...props} />
      </WalletModalProvider>
    );
  }

  // Self-contained: provide wallet-standard discovery + modal
  return (
    <WalletProvider wallets={EMPTY_ADAPTERS} localStorageKey="cedros-walletName">
      <WalletModalProvider>
        <SolanaLoginInner {...props} />
      </WalletModalProvider>
    </WalletProvider>
  );
}

function SolanaLoginInner({
  onSuccess,
  onError,
  className = '',
  variant = 'default',
  size = 'md',
  disabled = false,
  hideIfNoWallet = true,
  onLoadingChange,
  walletContext,
}: SolanaLoginButtonProps) {
  const { requestChallenge, signIn, isLoading: isAuthLoading } = useSolanaAuth();
  const adapterWallet = useWallet();
  const { visible: modalVisible, setVisible: setModalVisible } = useWalletModal();
  const [pendingLogin, setPendingLogin] = useState(false);
  const [triggerConnect, setTriggerConnect] = useState(false);
  const isProcessingRef = useRef(false);
  const modalWasOpen = useRef(false);
  const signRejectedRef = useRef(false);

  // Use walletContext if provided, otherwise use adapter's useWallet()
  const connected = walletContext?.connected ?? adapterWallet.connected;
  const connecting = walletContext?.connecting ?? adapterWallet.connecting;
  const publicKey = walletContext?.publicKey ?? adapterWallet.publicKey;
  const signMessage = walletContext?.signMessage ?? adapterWallet.signMessage;
  const wallet = walletContext?.wallet ?? adapterWallet.wallet;
  const wallets = walletContext?.wallets ?? adapterWallet.wallets;
  const select = walletContext
    ? walletContext.select
    : (name: string) => adapterWallet.select(name as WalletName);
  const connect = walletContext?.connect ?? adapterWallet.connect;

  // Get installed/ready wallets
  const installedWallets = wallets.filter(
    (w) => w.adapter.readyState === 'Installed' || w.adapter.readyState === 'Loadable'
  );

  // Execute the sign-in flow (challenge → sign → verify)
  const executeSignIn = useCallback(async () => {
    if (isProcessingRef.current) return;
    if (!publicKey || !signMessage) {
      onError?.(new Error('Wallet not ready'));
      return;
    }

    isProcessingRef.current = true;
    try {
      const pubKeyString = publicKey.toBase58();

      const challenge = await requestChallenge(pubKeyString);

      const messageBytes = new TextEncoder().encode(challenge.message);
      const signatureBytes = await signMessage(messageBytes);

      if (!(signatureBytes instanceof Uint8Array) || signatureBytes.length === 0) {
        throw new Error('Wallet returned invalid signature');
      }

      let signature: string;
      try {
        signature = btoa(String.fromCharCode(...signatureBytes));
      } catch {
        throw new Error('Failed to encode signature');
      }

      await signIn(pubKeyString, signature, challenge.message);
      signRejectedRef.current = false;
      onSuccess?.();
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      signRejectedRef.current = true;
      onError?.(error);
    } finally {
      isProcessingRef.current = false;
      setPendingLogin(false);
    }
  }, [publicKey, signMessage, requestChallenge, signIn, onSuccess, onError]);

  // Auto-connect when wallet is selected and triggerConnect is set
  useEffect(() => {
    if (triggerConnect && wallet && !connected && !connecting) {
      setTriggerConnect(false);
      connect().catch((err) => {
        onError?.(err instanceof Error ? err : new Error(String(err)));
        setPendingLogin(false);
      });
    }
  }, [triggerConnect, wallet, connected, connecting, connect, onError]);

  // Auto-execute sign-in when connected with pending login
  useEffect(() => {
    if (pendingLogin && connected && publicKey && signMessage && !isProcessingRef.current) {
      executeSignIn().catch(() => {
        /* Errors already passed to onError callback inside executeSignIn */
      });
    }
  }, [pendingLogin, connected, publicKey, signMessage, executeSignIn]);

  // When modal closes: connect if a wallet was selected, else reset.
  // Wallet is always deselected before opening, so any non-null wallet = user chose one.
  useEffect(() => {
    if (modalVisible) {
      modalWasOpen.current = true;
    } else if (modalWasOpen.current) {
      modalWasOpen.current = false;
      if (pendingLogin && !connected && wallet && !connecting) {
        setTriggerConnect(true);
      } else if (pendingLogin && !connected) {
        setPendingLogin(false);
      }
    }
  }, [modalVisible, pendingLogin, connected, wallet, connecting]);

  // Hide button if no wallets detected
  if (hideIfNoWallet && installedWallets.length === 0) {
    return null;
  }

  const handleClick = async () => {
    if (disabled || isAuthLoading || connecting) return;

    if (connected && publicKey && signMessage && !signRejectedRef.current) {
      // Already connected, previous attempt wasn't rejected — sign immediately
      setPendingLogin(true);
      await executeSignIn();
    } else if (installedWallets.length === 1 && !wallet) {
      // Single installed wallet, nothing remembered — auto-select + connect
      select(installedWallets[0].adapter.name);
      setPendingLogin(true);
      setTriggerConnect(true);
    } else {
      // Show wallet picker — deselect any remembered wallet first so that
      // every selection in the modal registers as "new" and dismissing
      // leaves wallet as null (no accidental auto-connect).
      signRejectedRef.current = false;
      if (wallet) {
        adapterWallet.select(null as unknown as WalletName);
      }
      setModalVisible(true);
      setPendingLogin(true);
    }
  };

  const sizeClasses = {
    sm: 'cedros-button-sm',
    md: 'cedros-button-md',
    lg: 'cedros-button-lg',
  };

  const variantClasses = {
    default: 'cedros-button-social',
    outline: 'cedros-button-social-outline',
  };

  const isLoading = isAuthLoading || connecting || (pendingLogin && !connected);

  // Notify parent of loading state changes
  useEffect(() => {
    onLoadingChange?.(isLoading);
  }, [isLoading, onLoadingChange]);

  return (
    <button
      type="button"
      className={`cedros-button ${variantClasses[variant]} ${sizeClasses[size]} ${className}`}
      onClick={handleClick}
      disabled={disabled || isLoading}
      aria-label="Continue with Solana"
    >
      {isLoading ? (
        <LoadingSpinner size="sm" />
      ) : (
        <svg
          className="cedros-button-icon"
          width="18"
          height="18"
          viewBox="0 0 128 128"
          fill="currentColor"
          aria-hidden="true"
        >
          <path d="M25.38 96.04a4.35 4.35 0 0 1 3.07-1.27h91.68c1.93 0 2.9 2.34 1.54 3.7l-17.71 17.72a4.35 4.35 0 0 1-3.07 1.27H9.21c-1.93 0-2.9-2.34-1.54-3.7l17.71-17.72z" />
          <path d="M25.38 11.81a4.47 4.47 0 0 1 3.07-1.27h91.68c1.93 0 2.9 2.34 1.54 3.7L103.96 31.96a4.35 4.35 0 0 1-3.07 1.27H9.21c-1.93 0-2.9-2.34-1.54-3.7L25.38 11.81z" />
          <path d="M102.62 53.76a4.35 4.35 0 0 0-3.07-1.27H7.87c-1.93 0-2.9 2.34-1.54 3.7l17.71 17.72a4.35 4.35 0 0 0 3.07 1.27h91.68c1.93 0 2.9-2.34 1.54-3.7L102.62 53.76z" />
        </svg>
      )}
      <span>Continue with Solana</span>
    </button>
  );
}
